def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = max(set(v for row in out for v in row), key=lambda v: sum(row.count(v) for row in out))
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    pairs.append((color, r, c, dr, dc))

    for color, r, c, dr, dc in pairs:
        def runway(sr, sc, step_r, step_c):
            count = 0
            while 0 <= sr < h and 0 <= sc < w and out[sr][sc] in (background, color):
                count += 1
                sr += step_r
                sc += step_c
            return count

        before = runway(r - dr, c - dc, -dr, -dc)
        after = runway(r + 2 * dr, c + 2 * dc, dr, dc)
        if before > after and before >= 2:
            rr, cc = r - dr, c - dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] in (background, color):
                out[rr][cc] = color
                rr -= dr
                cc -= dc
        elif after > before and after >= 2:
            rr, cc = r + 2 * dr, c + 2 * dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] in (background, color):
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for dr, dc in ((1, 1), (1, -1)):
        seen = set()
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or (r-dr, c-dc) in seen:
                    continue
                # This is the first point of a maximal diagonal run.
                run=[]; rr,cc=r,c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr,cc)); seen.add((rr,cc)); rr+=dr; cc+=dc
                if len(run) < 2:
                    continue
                for (er,ec), (sr,sc) in ((run[0],(-dr,-dc)), (run[-1],(dr,dc))):
                    blocked=False
                    for ar,ac in ((er-1,ec),(er+1,ec),(er,ec-1),(er,ec+1)):
                        if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] != bg:
                            blocked=True
                    if not blocked:
                        rr,cc=er+sr,ec+sc
                        while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                            out[rr][cc]=color; rr+=sr; cc+=sc
    return out

