def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    def mode_line(values):
        color, count = Counter(values).most_common(1)[0]
        return color != background and count > len(values) / 2
    rows = [r for r, row in enumerate(grid) if mode_line(row)]
    cols = [c for c in range(w) if mode_line([grid[r][c] for r in range(h)])]
    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        row = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            row.append(corners[0] if len(set(corners)) == 1 and corners[0] != background else background)
        out.append(row)
    while out and all(v == background for v in out[0]): out.pop(0)
    while out and all(v == background for v in out[-1]): out.pop()
    if out:
        while out and all(row[0] == background for row in out):
            for row in out: row.pop(0)
        while out and all(row[-1] == background for row in out):
            for row in out: row.pop()
    return out

