def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    line = counts.most_common(2)[1][0]
    special = {v for v in counts if v not in (bg, line)}
    rows = [r for r in range(h) if any(v in special for v in grid[r])]
    cols = [c for c in range(w) if any(grid[r][c] in special for r in range(h))]
    # The marker lattice can include a trailing extension; use the compact rectangular region.
    if len(rows) > len(cols) + 1:
        rows = rows[:len(cols) + 1]
    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]
    out = []
    for r0, r1 in zip(rows, rows[1:]):
        line_out = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            if len(set(corners)) == 1 and corners[0] in special:
                line_out.append(corners[0])
            else:
                line_out.append(bg)
        out.append(line_out)
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != background]
    if not colors:
        return out
    color = max(colors, key=lambda c: counts[c])
    # Work on the first band of non-background rows.
    rows = [r for r in range(h) if any(v != background for v in grid[r])]
    if not rows:
        return out
    start = rows[0]
    end = start
    while end + 1 < h and any(v != background for v in grid[end + 1]):
        end += 1
    band = range(start, end + 1)
    rightmost = max((c for r in band for c, v in enumerate(grid[r]) if v == color), default=-1)
    if rightmost < 0:
        return out
    # Extend the extremal row(s) to the right edge in red.
    for r in band:
        cols = [c for c, v in enumerate(grid[r]) if v == color]
        if cols and max(cols) == rightmost:
            for c in range(rightmost + 1, w):
                if grid[r][c] == background:
                    out[r][c] = 1
    # If the extreme marker sits at the right edge by itself, extend toward the left.
    if rightmost == w - 1:
        for r in band:
            cols = [c for c, v in enumerate(grid[r]) if v == color]
            if cols == [w - 1]:
                for c in range(w - 1):
                    if grid[r][c] == background:
                        out[r][c] = 1
    return out

